    if f.endswith('.ndjson'):
        for line in open(D+'/'+f):
            r=json.loads(line); res[r['resourceType']].append(r)
byid={r['id']:r for rs in res.values() for r in rs}
def ext(r,u,):
    for e in r.get('extension',[]):
        if e['url'].endswith('/'+u):
            for k,v in e.items():
                if k.startswith('value'): return v
    return None
def subj(r):
    for k in ('subject','patient','for'):
        if k in r: return r[k]['reference'].split('/')[-1]
    return None
pats={p['id']:p for p in res['Patient']}
eps=collections.defaultdict(list)
for e in res['EpisodeOfCare']: eps[e['patient']['reference'].split('/')[-1]].append(e)
recs=collections.defaultdict(list)
for t,rs in res.items():
    if t in ('Patient','EpisodeOfCare'): continue
    for r in rs:
        s=subj(r)
        if s: recs[s].append(r)
spec_by_id={s['id']:s for s in res['Specimen']}
acc_by_num=collections.defaultdict(list)
for b in res['Basic']:
    acc_by_num[ext(b,'accession')].append(b)
def et(r): return ext(r,'event-time') or r.get('date') or ''
json.dump({'note':'loaded'},open('/dev/null','w'))
